const std = @import("std");
pub const Tree = struct { value: i64, left: ?*const Tree = null, right: ?*const Tree = null };
pub const Store = struct {
    arena: std.heap.ArenaAllocator,
    pub fn init(a: std.mem.Allocator) Store {
        return .{ .arena = std.heap.ArenaAllocator.init(a) };
    }
    pub fn deinit(s: *Store) void {
        s.arena.deinit();
    }
};
const Crumb = struct { value: i64, sibling: ?*const Tree, left: bool };
pub const Zipper = struct {
    store: *Store,
    focus: *const Tree,
    crumbs: []const Crumb = &.{},
    pub fn fromTree(store: *Store, tree: *const Tree) Zipper {
        return .{ .store = store, .focus = tree };
    }
    pub fn value(z: Zipper) i64 {
        return z.focus.value;
    }
    fn node(z: Zipper, v: i64, l: ?*const Tree, r: ?*const Tree) !*const Tree {
        const n = try z.store.arena.allocator().create(Tree);
        n.* = .{ .value = v, .left = l, .right = r };
        return n;
    }
    pub fn setValue(z: Zipper, v: i64) !Zipper {
        var next = z;
        next.focus = try z.node(v, z.focus.left, z.focus.right);
        return next;
    }
    pub fn setLeft(z: Zipper, tree: ?*const Tree) !Zipper {
        var next = z;
        next.focus = try z.node(z.focus.value, tree, z.focus.right);
        return next;
    }
    pub fn setRight(z: Zipper, tree: ?*const Tree) !Zipper {
        var next = z;
        next.focus = try z.node(z.focus.value, z.focus.left, tree);
        return next;
    }
    fn down(z: Zipper, is_left: bool) !?Zipper {
        const child = (if (is_left) z.focus.left else z.focus.right) orelse return null;
        const crumbs = try z.store.arena.allocator().alloc(Crumb, z.crumbs.len + 1);
        @memcpy(crumbs[0..z.crumbs.len], z.crumbs);
        crumbs[z.crumbs.len] = .{ .value = z.focus.value, .sibling = if (is_left) z.focus.right else z.focus.left, .left = is_left };
        return Zipper{ .store = z.store, .focus = child, .crumbs = crumbs };
    }
    pub fn left(z: Zipper) !?Zipper {
        return z.down(true);
    }
    pub fn right(z: Zipper) !?Zipper {
        return z.down(false);
    }
    pub fn up(z: Zipper) !?Zipper {
        if (z.crumbs.len == 0) return null;
        const crumb = z.crumbs[z.crumbs.len - 1];
        const parent = try z.node(crumb.value, if (crumb.left) z.focus else crumb.sibling, if (crumb.left) crumb.sibling else z.focus);
        return Zipper{ .store = z.store, .focus = parent, .crumbs = z.crumbs[0 .. z.crumbs.len - 1] };
    }
    pub fn toTree(z: Zipper) !*const Tree {
        var current = z;
        while (try current.up()) |parent| current = parent;
        return current.focus;
    }
};

