// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("zipper.zig");
test "persistent navigation and editing from deep focus" {
    var store = m.Store.init(t.allocator);
    defer store.deinit();
    const leaf = m.Tree{ .value = 3 };
    const l = m.Tree{ .value = 2, .right = &leaf };
    const r = m.Tree{ .value = 4 };
    const root = m.Tree{ .value = 1, .left = &l, .right = &r };
    const z = m.Zipper.fromTree(&store, &root);
    try t.expect((try z.up()) == null);
    const left = (try z.left()).?;
    try t.expect((try left.left()) == null);
    try t.expectEqual(@as(i64, 2), left.value());
    const deep = (try left.right()).?;
    const changed = try deep.setValue(30);
    const rebuilt = try changed.toTree();
    try t.expectEqual(@as(i64, 30), rebuilt.left.?.right.?.value);
    try t.expectEqual(@as(i64, 3), root.left.?.right.?.value);
    try t.expectEqual(@as(i64, 1), z.value());
    try t.expectEqual(@as(i64, 3), deep.value());
    const removed = try (try changed.up()).?.setRight(null);
    try t.expect((try removed.right()) == null);
    const pruned = try (try removed.up()).?.setLeft(null);
    try t.expect((try pruned.left()) == null);
    try t.expectEqual(@as(i64, 4), (try pruned.right()).?.value());
    const inserted = try pruned.setLeft(&leaf);
    try t.expectEqual(@as(i64, 3), (try inserted.left()).?.value());
}

fn sameBinary(a: ?*const m.Tree, b: ?*const m.Tree) anyerror!void {
    try t.expectEqual(a == null, b == null);
    if (a) |x| {
        const y = b.?;
        try t.expectEqual(y.value, x.value);
        try sameBinary(x.left, y.left);
        try sameBinary(x.right, y.right);
    }
}
